import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.BeNN5tyQ.js";const h=JSON.parse('{"title":"MutationObserver","description":"","frontmatter":{},"headers":[],"relativePath":"browser/mutation-observer.md","filePath":"browser/mutation-observer.md"}'),i={name:"browser/mutation-observer.md"};function s(n,e,l,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mutationobserver" tabindex="-1">MutationObserver <a class="header-anchor" href="#mutationobserver" aria-label="Permalink to &quot;MutationObserver&quot;">​</a></h1><div><h2 id="що-таке-mutationobserver" tabindex="-1">Що таке MutationObserver? <a class="header-anchor" href="#що-таке-mutationobserver" aria-label="Permalink to &quot;Що таке MutationObserver?&quot;">​</a></h2><ul><li><strong><code>MutationObserver</code></strong> — це вбудований об’єкт, який спостерігає за вибраним елементом DOM і викликає функцію зворотного виклику, щоразу коли помічає в ньому зміни.</li></ul><h2 id="що-саме-він-може-відстежувати" tabindex="-1">Що саме він може відстежувати? <a class="header-anchor" href="#що-саме-він-може-відстежувати" aria-label="Permalink to &quot;Що саме він може відстежувати?&quot;">​</a></h2><ul><li>За допомогою об&#39;єкта конфігурації можна точно вказати, на які саме зміни потрібно реагувати.</li><li>Він може спостерігати за додаванням чи видаленням безпосередніх нащадків (<code>childList</code>), за змінами у всіх нащадках вузла (<code>subtree</code>), за змінами атрибутів (<code>attributes</code>), а також за змінами текстового вмісту (<code>characterData</code>).</li></ul><h2 id="головні-юзкеиси-навіщо-це-потрібно-на-практиці" tabindex="-1">Головні юзкейси (навіщо це потрібно на практиці) <a class="header-anchor" href="#головні-юзкеиси-навіщо-це-потрібно-на-практиці" aria-label="Permalink to &quot;Головні юзкейси (навіщо це потрібно на практиці)&quot;">​</a></h2><ul><li><strong>Інтеграція зі сторонніми скриптами:</strong> Дозволяє відстежити, коли стороння бібліотека (наприклад, віджет чи плагін) додає небажаний елемент (наприклад, рекламу) у ваш DOM, і програмно його видалити, оскільки такий скрипт часто не надає власних механізмів для очищення.</li><li><strong>Архітектурні рішення:</strong> Зручна обробка динамічно завантаженого контенту. Наприклад, якщо якийсь модуль сайту динамічно завантажує статтю з сервера і вставляє її в сторінку, <code>MutationObserver</code> може автоматично виявити нові фрагменти коду в цьому HTML та застосувати до них підсвітку синтаксису в одному місці, позбавляючи необхідності робити це вручну після кожного завантаження.</li></ul><h2 id="важливі-методи-та-нюанси" tabindex="-1">Важливі методи та нюанси <a class="header-anchor" href="#важливі-методи-та-нюанси" aria-label="Permalink to &quot;Важливі методи та нюанси&quot;">​</a></h2><ul><li>Щоб зупинити спостереження, використовується метод <code>observer.disconnect()</code>.</li><li>Метод <code>observer.takeRecords()</code> отримує перелік необроблених мутацій — тих, що вже трапилися, але ще не були опрацьовані функцією зворотного виклику. При цьому записи, повернуті цим методом, видаляються із черги обробки.</li><li><strong>Взаємодія зі збирачем сміття (Garbage Collection):</strong> Усередині спостерігачів використовуються слабкі посилання на вузли. Це означає, що сам факт спостереження за вузлом не блокує процес збирання сміття: якщо вузол видаляється з DOM і стає недоступним, збирач сміття зможе його прибрати з пам&#39;яті.</li></ul></div>',2)])])}const m=r(i,[["render",s]]);export{h as __pageData,m as default};
